label.text:
model -> {
	period = ifElse(isEmpty($model),
		new(`tl.ai.monitor:Period`, transient: true)
			..set(`tl.ai.monitor:Period#preset`, 30),
		$model);
	#('Tokens ({0})'@en, 'Token ({0})'@de)
		.fill($period.get(`tl.ai.monitor:Period#label`)).localize();
}

description.text:
model -> {
	period = ifElse(isEmpty($model),
		new(`tl.ai.monitor:Period`, transient: true)
			..set(`tl.ai.monitor:Period#preset`, 30),
		$model);
	executions = all(`tl.ai.execution:AgentExecution`);
	startedAt = e -> $e.get(`tl.ai.execution:AgentExecution#startedAt`);
	start = $period.get(`tl.ai.monitor:Period#windowStart`);
	end = $period.get(`tl.ai.monitor:Period#windowEnd`);
	// A bound that is empty is dropped rather than tested. A period is normally a closed day
	// range with both ends filled - even "Alle", which reads them off the data - but one that
	// was never filled has no edges, and then it selects everything.
	recent = $executions.filter(e -> (isEmpty($start) || $startedAt($e) >= $start)
		&& (isEmpty($end) || $startedAt($e) < $end));
	value = a -> e -> ifElse(isEmpty($e.get($a)), 0, $e.get($a));
	billable = $recent.map(e -> $value(`tl.ai.execution:AgentExecution#inputTokens`)($e)
		+ $value(`tl.ai.execution:AgentExecution#outputTokens`)($e)).sum();
	cached = $recent.map(e -> $value(`tl.ai.execution:AgentExecution#cacheReadTokens`)($e)).sum();
	priced = $recent.filter(e -> !isEmpty($e.get(`tl.ai.execution:AgentExecution#cost`)));
	byCurrency = $priced.groupBy(e -> $e.get(`tl.ai.execution:AgentExecution#currency`));
	cost = $byCurrency.keySet().toList().sort()
		.map(c -> numberFormat('#,##0.00').format($byCurrency[$c]
			.map(e -> $e.get(`tl.ai.execution:AgentExecution#cost`)).sum()) + ' ' + $c)
		.join(' + ');
	// A seven-digit number is not a number a reader takes in at a glance; the exact value is one
	// click away in the table behind this tile.
	short = v -> $v >= 1000000
		? numberFormat('#,##0.0').format($v / 1000000) + ' Mio.'
		: numberFormat('#,##0').format($v);
	{{{
		<div class="aiKpi">
			<div class="aiKpiValue">{$short($billable)}</div>
			<div class="aiKpiNote">
				{#('billable, {0} from the cache'@en, 'abrechenbar, {0} aus dem Cache'@de).fill($short($cached))}
			</div>
			<div class="aiKpiNote">
				{#('Cost: {0}'@en, 'Kosten: {0}'@de).fill(ifElse(isEmpty($cost), '-', $cost))}
			</div>
		</div>
	}}};
}

modelBuilder.elements:
model -> {
	period = ifElse(isEmpty($model),
		new(`tl.ai.monitor:Period`, transient: true)
			..set(`tl.ai.monitor:Period#preset`, 30),
		$model);
	executions = all(`tl.ai.execution:AgentExecution`);
	startedAt = e -> $e.get(`tl.ai.execution:AgentExecution#startedAt`);
	start = $period.get(`tl.ai.monitor:Period#windowStart`);
	end = $period.get(`tl.ai.monitor:Period#windowEnd`);
	// A bound that is empty is dropped rather than tested. A period is normally a closed day
	// range with both ends filled - even "Alle", which reads them off the data - but one that
	// was never filled has no edges, and then it selects everything.
	recent = $executions.filter(e -> (isEmpty($start) || $startedAt($e) >= $start)
		&& (isEmpty($end) || $startedAt($e) < $end));
	$recent;
}
